// --- INFORMACOES DA RACA ---
std::string Mahoraga::obterNomeRaca() const { 
    return "General Divino Imoral da Espada de Oito Empunhaduras, Mahoraga"; 
}

Atributos Mahoraga::obterAtributosRaca() const { 
    return { 1000, 0, 0, 0, 0, 0, 0 }; 
}

