const std::vector<std::string>& Mahoraga::obterAparenciaCombate() const
{
    static std::vector<std::string> aparenciaReduzida;
    if (aparenciaReduzida.empty())
    {
        // Fator de compressão (X e Y) definido localmente para este inimigo
        aparenciaReduzida = Aparencia::reduzirEscalaAscii(obterAparenciaRaca(), 3, 4);
    }
    return aparenciaReduzida;
}

// --- BESTIARIO E DROPS ---
InfoBestiario Mahoraga::obterInfoBestiario() const {
    return {
        "Labirinto Subterraneo", 
        "Sala do Chefe",
        "Uma entidade lendaria de oito empunhaduras selada na escuridao. A roda sobre sua cabeca gira, adaptando-se a todos e quaisquer fenomenos.",
        "Dizem que o unico jeito de derrota-lo e com um golpe fulminante antes que a roda gire.",
        {"Ouro Massivo", "Espada de Exterminio", "Roda da Adaptacao", FabricaItens::obterNomeDeID(ItemID::PedraUpgrade), FabricaItens::obterNomeDeID(ItemID::PocaoFuria), FabricaItens::obterNomeDeID(ItemID::ElixirArcano)},
        10 // Dificuldade Maxima!
    };
}

void Mahoraga::realizarDrops(SistemaPersonagem* inimigo, SistemaPersonagem* jogadorAtual, std::vector<std::string>& itensObtidos, int& ouroTotal, int& xpTotal) {
    GerenciadorDrops::relatarEProcessarXpOuro(jogadorAtual, 5000, 5000, ouroTotal, xpTotal);
    
    GerenciadorDrops::darEProcessarItem(jogadorAtual, ItemID::EspadaExterminio, 1, itensObtidos);
    GerenciadorDrops::darEProcessarItem(jogadorAtual, ItemID::RodaAdaptacao, 1, itensObtidos);
    GerenciadorDrops::darEProcessarItem(jogadorAtual, ItemID::PedraUpgrade, 3, itensObtidos);
    GerenciadorDrops::darEProcessarItem(jogadorAtual, ItemID::PocaoFuria, 3, itensObtidos);
    GerenciadorDrops::darEProcessarItem(jogadorAtual, ItemID::ElixirArcano, 3, itensObtidos);
}
